create extension if not exists "pgcrypto";
create table if not exists public.businesses(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null,slug text not null unique,tagline text,phone text,address text,logo_url text,created_at timestamptz default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,name text not null,description text,price numeric default 0,image_url text,active boolean not null default true,created_at timestamptz default now());
create table if not exists public.services(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,name text not null,description text,price numeric default 0,active boolean not null default true,created_at timestamptz default now());
create table if not exists public.requests(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,customer_id uuid references auth.users(id) on delete set null,type text not null check(type in('order','booking')),item_name text,customer_name text not null,customer_phone text,note text,status text default 'pending',created_at timestamptz default now());
alter table public.requests add column if not exists customer_id uuid references auth.users(id) on delete set null;
alter table public.requests add column if not exists item_name text;
alter table public.requests add column if not exists customer_name text;
alter table public.requests add column if not exists customer_phone text;
alter table public.requests add column if not exists note text;
alter table public.requests add column if not exists status text default 'pending';
alter table public.requests add column if not exists created_at timestamptz default now();
alter table public.businesses enable row level security;alter table public.products enable row level security;alter table public.services enable row level security;alter table public.requests enable row level security;
drop policy if exists "public read businesses" on public.businesses;drop policy if exists "owner manage businesses" on public.businesses;drop policy if exists "public read products" on public.products;drop policy if exists "owner manage products" on public.products;drop policy if exists "public read services" on public.services;drop policy if exists "owner manage services" on public.services;drop policy if exists "customer insert requests" on public.requests;drop policy if exists "customer read own requests" on public.requests;drop policy if exists "owner read business requests" on public.requests;drop policy if exists "owner update business requests" on public.requests;drop policy if exists "customer_insert_requests" on public.requests;drop policy if exists "customer_read_requests" on public.requests;
create policy "public read businesses" on public.businesses for select using(true);create policy "owner manage businesses" on public.businesses for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "public read products" on public.products for select using(active=true or exists(select 1 from public.businesses b where b.id=products.business_id and b.owner_id=auth.uid()));create policy "owner manage products" on public.products for all to authenticated using(exists(select 1 from public.businesses b where b.id=products.business_id and b.owner_id=auth.uid())) with check(exists(select 1 from public.businesses b where b.id=products.business_id and b.owner_id=auth.uid()));
create policy "public read services" on public.services for select using(active=true or exists(select 1 from public.businesses b where b.id=services.business_id and b.owner_id=auth.uid()));create policy "owner manage services" on public.services for all to authenticated using(exists(select 1 from public.businesses b where b.id=services.business_id and b.owner_id=auth.uid())) with check(exists(select 1 from public.businesses b where b.id=services.business_id and b.owner_id=auth.uid()));
create policy "customer insert requests" on public.requests for insert to authenticated with check(customer_id=auth.uid());create policy "customer read own requests" on public.requests for select to authenticated using(customer_id=auth.uid());create policy "owner read business requests" on public.requests for select to authenticated using(exists(select 1 from public.businesses b where b.id=requests.business_id and b.owner_id=auth.uid()));create policy "owner update business requests" on public.requests for update to authenticated using(exists(select 1 from public.businesses b where b.id=requests.business_id and b.owner_id=auth.uid())) with check(exists(select 1 from public.businesses b where b.id=requests.business_id and b.owner_id=auth.uid()));
